package com.example.notes;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

/** Plain-file notes kept under one directory. */
public final class Notes {
    private Notes() {
    }

    public static String read(Path root, String name) throws IOException {
        Path base = root.toAbsolutePath().normalize();
        Path file = base.resolve(name).normalize();
        if (!file.startsWith(base) || !Files.isRegularFile(file)) {
            return null;
        }
        return new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
    }
}

package com.example.notes;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class NotesTest {
    @TempDir
    Path root;

    @Test
    void readsExistingNote() throws Exception {
        Files.write(root.resolve("todo.txt"), "milk".getBytes(StandardCharsets.UTF_8));
        assertEquals("milk", Notes.read(root, "todo.txt"));
    }
}
